python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
wb=load_workbook('/root/data/workbook.xlsx', data_only=False)
for s in ['Data','Task']:
    ws=wb[s]
    print(f'\n{s} dimensions: {ws.max_row} rows x {ws.max_column} cols')
    print('Non-empty cells in first 60 rows x 20 cols:')
    for r in range(1, min(ws.max_row,60)+1):
        entries=[]
        for c in range(1, min(ws.max_column,20)+1):
            v=ws.cell(r,c).value
            if v is not None:
                entries.append(f'{get_column_letter(c)}{r}={v!r}')
        if entries:
            print('; '.join(entries))
print('\nTask target H:L rows 8-52 fill details for empty cells:')
ws=wb['Task']
for r in range(8,53):
    entries=[]
    for c in range(8,13):
        cell=ws.cell(r,c)
        if cell.value is None:
            fill=cell.fill
            entries.append(f'{get_column_letter(c)}{r}:pattern={fill.patternType},fg_type={fill.fgColor.type},fg_rgb={fill.fgColor.rgb},fg_idx={fill.fgColor.indexed},fg_theme={fill.fgColor.theme},fg_tint={fill.fgColor.tint}')
    if entries:
        print(' | '.join(entries))
